import java.io.*;public class Driver {static class Student implements Serializable{int id;String name;transient String password;Student(int i,String n,String p){id=i;name=n;password=p;}public String toString(){return "Student [id="+id+", name="+name+", password="+password+"]";}}public static void main(String[]a)throws Exception{File f=new File("students.dat");Student s=new Student(101,"Manav","secretPass");try(var out=new ObjectOutputStream(new FileOutputStream(f))){out.writeObject(s);}try(var in=new ObjectInputStream(new FileInputStream(f))){System.out.println("Original: "+s);System.out.println("Loaded:   "+in.readObject());}f.delete();}}
